int num = 0;
do {
    System.out.println(num);
    num++;
} while (num <= 10);

int n = 100;

while (n <= 10) {          // condition false immediately
    System.out.println(n); //   → body never runs
}

do {
    System.out.println(n); //   → body runs once, printing 100
} while (n <= 10);

Scanner input = new Scanner(System.in);
int choice;
do {
    System.out.print("Enter 1-5: ");
    choice = input.nextInt();
} while (choice < 1 || choice > 5);
System.out.println("You chose " + choice);
